import os
import csv
import re

def analyze_logs(target_dir):
    results = []
    # Regex for exact match of level in 3rd column (space separated)
    # Format expected: DATE TIME LEVEL MESSAGE...
    # We split by whitespace and check index 2 (0-based)

    for root, dirs, files in os.walk(target_dir):
        for file in files:
            if file.endswith('.log') and not file.endswith('.log.'):
                file_path = os.path.join(root, file)
                rel_path = os.path.relpath(file_path, target_dir).replace('\\', '/')

                counts = {'ERROR': 0, 'WARN': 0, 'INFO': 0}

                try:
                    with open(file_path, 'r', encoding='utf-8', errors='ignore') as f:
                        for line in f:
                            parts = line.split()
                            if len(parts) >= 3:
                                level = parts[2]
                                if level in counts:
                                    counts[level] += 1
                except Exception as e:
                    print(f"Hata okurken {file_path}: {e}")
                    continue

                results.append({
                    'dosya': rel_path,
                    'error': counts['ERROR'],
                    'warn': counts['WARN'],
                    'info': counts['INFO']
                })
            elif file.endswith('.log') and not file.endswith('.log.'):
                 # This part is handled by the logic above, but ensuring we catch all .log
                 pass

    # Sort: error descending, then path ascending
    results.sort(key=lambda x: (-x['error'], x['dosya']))
    return results

def main():
    target_dir = 'loglar'
    output_file = 'rapor.csv'

    if not os.path.exists(target_dir):
        print(f"Hata: {target_dir} klasörü bulunamadı.")
        return

    data = analyze_logs(target_dir)

    with open(output_file, 'w', newline='', encoding='utf-8') as csvfile:
        fieldnames = ['dosya', 'error', 'warn', 'info']
        writer = csv.DictWriter(csvfile, fieldnames=fieldnames)
        writer.writeheader()
        for row in data:
            writer.writerow(row)

if __name__ == "__main__":
    main()

